(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit62-trap-c4-basic-1"]={"id":"unit62-trap-c4-basic-1","unitId":"6-2","chapterIds":["6-2"],"unitType":"basic","group":"6-2단원 · 선지 변형 유형 · 비교","name":"기본 OX 1","level":"기본","revision":3,"resetReviewOnRevision":true,"originPage":"unit62","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"비교","parts":[{"name":"U62-H01-02-B1 · 연결하는 작업의 뜻","items":[{"paragraphCount":1,"readingLabel":"1문단 · 핵심 읽기 2/5단계","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 1문단","passage":"[핵심 문장 · 1문단]\n이는 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 연결하는 작업이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"‘연결하다’는 서로 잇는다는 뜻이다. 디자인은 사람과 공간, 자연과 마음 등을 이어 주는 일이다.\n근거: “이는 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 연결하는 작업이다.”","evidence":{"title":"연결하는 작업의 뜻","statement":"‘~을 연결하는 작업이다’는 디자인이 여러 대상을 서로 이어 주는 일이라는 뜻이다.","explanation":"‘연결하다’는 서로 잇는다는 뜻이다. 디자인은 사람과 공간, 자연과 마음 등을 이어 주는 일이다.\n근거: “이는 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 연결하는 작업이다.”","valid":["G01:4"],"sources":[{"id":"G01","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"1문단","sentences":[{"id":"G01:4","text":"이는 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 연결하는 작업이다.","paragraph":0,"memberIds":["G01:4"],"topic":"이것(디자인)은 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 서로 이어 주는 일이다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"G01:4","text":"이는 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 연결하는 작업이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U62-H01-02-B1","type":"ox","answer":"O","changed":"‘~을 연결하는 작업이다’는 디자인이 여러 대상을 서로 이어 주는 일이라는 뜻이다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":2,"progressiveTotal":5,"progressiveLabel":"표현 바꿔 읽기","learningFocus":"연결하는 작업의 뜻","hintGuide":"‘연결하는’을 쉬운 말로 바꾸어 보세요.","synthesis":false,"editorSourceVersion":"aa52c342aa03a24fce4525f6bd1b750885061757273444438c790c5dd9e22c47"}]},{"name":"U62-H01-05-B1 · 1문단의 핵심","items":[{"paragraphCount":1,"readingLabel":"1문단 · 핵심 읽기 5/5단계","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 1문단","passage":"[문단 전체 · 1문단]\n우리는 도시나 건축을 디자인한다. 자신이 살고 있는 집도 디자인하고 사회적 약자들을 위한 공간도 디자인한다. 디자인에는 어떤 목적이나 의도를 가지고 대상 혹은 공간을 가꾼다는 의미가 담겨 있다. 이는 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 연결하는 작업이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"1문단은 디자인을 목적·의도를 가지고 공간을 가꾸는 일, 여러 대상을 연결하는 작업으로 설명한다.\n근거: “디자인에는 어떤 목적이나 의도를 가지고 대상 혹은 공간을 가꾼다는 의미가 담겨 있다.” “이는 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 연결하는 작업이다.”","evidence":{"title":"1문단의 핵심","statement":"1문단은 디자인이 목적을 가지고 공간을 가꾸어 사람과 공간, 자연과 마음 등을 잇는 일이라고 설명한다.","explanation":"1문단은 디자인을 목적·의도를 가지고 공간을 가꾸는 일, 여러 대상을 연결하는 작업으로 설명한다.\n근거: “디자인에는 어떤 목적이나 의도를 가지고 대상 혹은 공간을 가꾼다는 의미가 담겨 있다.” “이는 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 연결하는 작업이다.”","valid":["G01:3","G01:4"],"sources":[{"id":"G01","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"1문단","sentences":[{"id":"G01:1","text":"우리는 도시나 건축을 디자인한다.","paragraph":0,"memberIds":["G01:1"],"topic":"우리는 도시와 건물을 디자인한다."},{"id":"G01:2","text":"자신이 살고 있는 집도 디자인하고 사회적 약자들을 위한 공간도 디자인한다.","paragraph":0,"memberIds":["G01:2"],"topic":"내가 사는 집도 디자인하고, 사회에서 도움이 더 필요한 사람들(사회적 약자)을 위한 공간도 디자인한다."},{"id":"G01:3","text":"디자인에는 어떤 목적이나 의도를 가지고 대상 혹은 공간을 가꾼다는 의미가 담겨 있다.","paragraph":0,"memberIds":["G01:3"],"topic":"디자인한다는 말에는 어떤 목적이나 생각(의도)을 가지고 물건이나 공간을 가꾼다는 뜻이 들어 있다."},{"id":"G01:4","text":"이는 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 연결하는 작업이다.","paragraph":0,"memberIds":["G01:4"],"topic":"이것(디자인)은 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 서로 이어 주는 일이다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"G01:3","text":"디자인에는 어떤 목적이나 의도를 가지고 대상 혹은 공간을 가꾼다는 의미가 담겨 있다."},{"id":"G01:4","text":"이는 사람과 공간, 공간과 건축, 건축과 도시, 도시와 자연, 자연과 마음을 연결하는 작업이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U62-H01-05-B1","type":"ox","answer":"O","changed":"1문단은 디자인이 목적을 가지고 공간을 가꾸어 사람과 공간, 자연과 마음 등을 잇는 일이라고 설명한다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"1문단의 핵심","hintGuide":"1문단이 디자인을 어떤 일이라고 하는지 두 문장을 묶어 보세요.","synthesis":true,"editorSourceVersion":"e1d13e9ce1747225c227cc4e91d27dd3784694299a6fd91b427362d9beece74d"}]},{"name":"U62-H02-02-B1 · 꾸려 가다의 뜻","items":[{"paragraphCount":1,"readingLabel":"2문단 · 핵심 읽기 2/5단계","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 2문단","passage":"[핵심 문장 · 2문단]\n좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"‘꾸려 가다’는 일을 잘 이끌어 나간다는 뜻이다.\n근거: “좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다.”","evidence":{"title":"꾸려 가다의 뜻","statement":"가꿈은 좋은 상태로 만들려고 보살피며 잘 이끌어 가는 일이라고 바꾸어 말할 수 있다.","explanation":"‘꾸려 가다’는 일을 잘 이끌어 나간다는 뜻이다.\n근거: “좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다.”","valid":["G02:2"],"sources":[{"id":"G02","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"2문단","sentences":[{"id":"G02:2","text":"좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다.","paragraph":0,"memberIds":["G02:2"],"topic":"다시 말해 좋은 상태로 만들려고 보살피고 잘 이끌어 가는(꾸려 가는) 일이다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"G02:2","text":"좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U62-H02-02-B1","type":"ox","answer":"O","changed":"가꿈은 좋은 상태로 만들려고 보살피며 잘 이끌어 가는 일이라고 바꾸어 말할 수 있다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":2,"progressiveTotal":5,"progressiveLabel":"표현 바꿔 읽기","learningFocus":"꾸려 가다의 뜻","hintGuide":"‘꾸려 가는’을 쉬운 말로 바꾸어 보세요.","synthesis":false,"editorSourceVersion":"e2b9219bbaca346c9de39f34bc139acec814c6fcb41822e65d2bd4ecde78df90"}]},{"name":"U62-H02-04-B1 · 가꿈·돌봄과 관리의 대조","items":[{"paragraphCount":1,"readingLabel":"2문단 · 핵심 읽기 4/5단계","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 2문단","passage":"[핵심 문장 · 2문단]\n단순히 도시와 건축을 관리하는 것은 보살핌이 아니다. 어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다. 그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"가꿈·돌봄은 보살핌이고 단순한 관리는 보살핌이 아니며, 관리 안에는 안전함과 편안함이 없다.\n근거: “단순히 도시와 건축을 관리하는 것은 보살핌이 아니다.” “어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.” “그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.”","evidence":{"title":"가꿈·돌봄과 관리의 대조","statement":"2문단은 가꿈·돌봄과 단순한 관리를 맞세워, 관리에는 안전함과 편안함이 없다고 한다.","explanation":"가꿈·돌봄은 보살핌이고 단순한 관리는 보살핌이 아니며, 관리 안에는 안전함과 편안함이 없다.\n근거: “단순히 도시와 건축을 관리하는 것은 보살핌이 아니다.” “어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.” “그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.”","valid":["G02:5","G02:6","G02:7"],"sources":[{"id":"G02","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"2문단","sentences":[{"id":"G02:5","text":"단순히 도시와 건축을 관리하는 것은 보살핌이 아니다.","paragraph":0,"memberIds":["G02:5"],"topic":"도시와 건물을 그저 관리하기만 하는 것은 보살핌이 아니다."},{"id":"G02:6","text":"어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.","paragraph":0,"memberIds":["G02:6"],"topic":"배려나 공감 없이 법에서 정한 가장 낮은 기준(최소한의 법적 요건)만 맞추어 계획하는 것은 겉모습만 꾸미는 '관리'일 뿐이다."},{"id":"G02:7","text":"그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.","paragraph":0,"memberIds":["G02:7"],"topic":"그렇게 만든 공간에는 돌봄과 가꿈이 주는 안전함과 편안함이 없다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"G02:5","text":"단순히 도시와 건축을 관리하는 것은 보살핌이 아니다."},{"id":"G02:6","text":"어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다."},{"id":"G02:7","text":"그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U62-H02-04-B1","type":"ox","answer":"O","changed":"2문단은 가꿈·돌봄과 단순한 관리를 맞세워, 관리에는 안전함과 편안함이 없다고 한다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"가꿈·돌봄과 관리의 대조","hintGuide":"가꿈·돌봄과 관리가 어떻게 다른지 뒤쪽 세 문장에서 보세요.","synthesis":false,"editorSourceVersion":"70636153a9a2eac2cadcd196997bf06b03a0037acaeef3c017b2be586a68da2b"}]},{"name":"U62-H02-05-B1 · 2문단의 핵심","items":[{"paragraphCount":1,"readingLabel":"2문단 · 핵심 읽기 5/5단계","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 2문단","passage":"[문단 전체 · 2문단]\n‘가꿈’은 식물이나 그것을 기르는 장소 등을 손질하고 보살핀다는 의미이다. 좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다. ‘돌봄’은 관심 있게 보살피는 것을 의미한다. 두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다. 단순히 도시와 건축을 관리하는 것은 보살핌이 아니다. 어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다. 그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"2문단은 가꿈과 돌봄의 공통 의미를 지속적인 보살핌으로 묶고, 겉모습을 꾸미기만 하는 관리와 대조한다.\n근거: “두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다.” “어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.”","evidence":{"title":"2문단의 핵심","statement":"2문단은 가꿈과 돌봄을 지속적인 보살핌으로 보고, 겉모습만 꾸미는 관리와 구별한다.","explanation":"2문단은 가꿈과 돌봄의 공통 의미를 지속적인 보살핌으로 묶고, 겉모습을 꾸미기만 하는 관리와 대조한다.\n근거: “두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다.” “어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.”","valid":["G02:4","G02:6"],"sources":[{"id":"G02","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"2문단","sentences":[{"id":"G02:1","text":"‘가꿈’은 식물이나 그것을 기르는 장소 등을 손질하고 보살핀다는 의미이다.","paragraph":0,"memberIds":["G02:1"],"topic":"'가꿈'은 식물이나 식물을 기르는 곳을 손질하고 보살핀다는 뜻이다."},{"id":"G02:2","text":"좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다.","paragraph":0,"memberIds":["G02:2"],"topic":"다시 말해 좋은 상태로 만들려고 보살피고 잘 이끌어 가는(꾸려 가는) 일이다."},{"id":"G02:3","text":"‘돌봄’은 관심 있게 보살피는 것을 의미한다.","paragraph":0,"memberIds":["G02:3"],"topic":"'돌봄'은 관심을 가지고 보살피는 것을 뜻한다."},{"id":"G02:4","text":"두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다.","paragraph":0,"memberIds":["G02:4"],"topic":"두 낱말 모두 정성을 다해 대상이나 공간을 지키면서, 관심을 두고 꾸준히(지속해서) 보살피는 일을 뜻한다."},{"id":"G02:5","text":"단순히 도시와 건축을 관리하는 것은 보살핌이 아니다.","paragraph":0,"memberIds":["G02:5"],"topic":"도시와 건물을 그저 관리하기만 하는 것은 보살핌이 아니다."},{"id":"G02:6","text":"어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.","paragraph":0,"memberIds":["G02:6"],"topic":"배려나 공감 없이 법에서 정한 가장 낮은 기준(최소한의 법적 요건)만 맞추어 계획하는 것은 겉모습만 꾸미는 '관리'일 뿐이다."},{"id":"G02:7","text":"그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.","paragraph":0,"memberIds":["G02:7"],"topic":"그렇게 만든 공간에는 돌봄과 가꿈이 주는 안전함과 편안함이 없다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"G02:4","text":"두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다."},{"id":"G02:6","text":"어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U62-H02-05-B1","type":"ox","answer":"O","changed":"2문단은 가꿈과 돌봄을 지속적인 보살핌으로 보고, 겉모습만 꾸미는 관리와 구별한다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"2문단의 핵심","hintGuide":"2문단에서 묶이는 것과 대조되는 것을 나누어 보세요.","synthesis":true,"editorSourceVersion":"985f6d053f9f28651f93cb3f62779454092c16ecfcc38609485dafea5a0c47fa"}]},{"name":"U62-E01-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"2문단 · 새 예시 적용","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 2문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 2문단]\n‘가꿈’은 식물이나 그것을 기르는 장소 등을 손질하고 보살핀다는 의미이다. 좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다. ‘돌봄’은 관심 있게 보살피는 것을 의미한다. 두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다. 단순히 도시와 건축을 관리하는 것은 보살핌이 아니다. 어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다. 그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n서윤이네 반 창가에는 화분이 두 개 있다. 서윤이는 날마다 흙이 말랐는지 살피고 물을 주며 한 화분을 돌본다. 다른 화분은 겉에 예쁜 그림만 그려 놓고, 점검표에 ‘물 주기 ✓’만 적어 두었다. 흙이 바싹 말라도 아무도 들여다보지 않았다. 한 달 뒤, 서윤이가 돌본 화분은 꽃을 피웠고, 겉만 꾸민 화분은 시들어 버렸다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"날마다 살피고 물을 주는 서윤이는 관심을 두고 지속해서 보살피는 가꿈·돌봄에, 겉에 그림만 그리고 점검표에 ✓만 적은 화분은 배려·공감 없이 법적 요건만 갖춘 관리(겉모습만 꾸미기)에 대응한다. 시든 화분은 안전함과 편안함이 없는 공간과 같다.\n근거: “두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다.” “어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.” “그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.”\n2문단에서 확인할 수 있어요.","evidence":{"title":"교실 창가의 화분 두 개","statement":"점검표에 ✓만 적은 화분은 겉모습만 꾸민 관리에 해당한다.","explanation":"날마다 살피고 물을 주는 서윤이는 관심을 두고 지속해서 보살피는 가꿈·돌봄에, 겉에 그림만 그리고 점검표에 ✓만 적은 화분은 배려·공감 없이 법적 요건만 갖춘 관리(겉모습만 꾸미기)에 대응한다. 시든 화분은 안전함과 편안함이 없는 공간과 같다.\n근거: “두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다.” “어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.” “그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.”\n2문단에서 확인할 수 있어요.","valid":["G02:4","G02:6","G02:7"],"sources":[{"id":"G02","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"2문단","sentences":[{"id":"G02:1","text":"‘가꿈’은 식물이나 그것을 기르는 장소 등을 손질하고 보살핀다는 의미이다.","paragraph":0,"memberIds":["G02:1"],"topic":"'가꿈'은 식물이나 식물을 기르는 곳을 손질하고 보살핀다는 뜻이다."},{"id":"G02:2","text":"좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다.","paragraph":0,"memberIds":["G02:2"],"topic":"다시 말해 좋은 상태로 만들려고 보살피고 잘 이끌어 가는(꾸려 가는) 일이다."},{"id":"G02:3","text":"‘돌봄’은 관심 있게 보살피는 것을 의미한다.","paragraph":0,"memberIds":["G02:3"],"topic":"'돌봄'은 관심을 가지고 보살피는 것을 뜻한다."},{"id":"G02:4","text":"두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다.","paragraph":0,"memberIds":["G02:4"],"topic":"두 낱말 모두 정성을 다해 대상이나 공간을 지키면서, 관심을 두고 꾸준히(지속해서) 보살피는 일을 뜻한다."},{"id":"G02:5","text":"단순히 도시와 건축을 관리하는 것은 보살핌이 아니다.","paragraph":0,"memberIds":["G02:5"],"topic":"도시와 건물을 그저 관리하기만 하는 것은 보살핌이 아니다."},{"id":"G02:6","text":"어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.","paragraph":0,"memberIds":["G02:6"],"topic":"배려나 공감 없이 법에서 정한 가장 낮은 기준(최소한의 법적 요건)만 맞추어 계획하는 것은 겉모습만 꾸미는 '관리'일 뿐이다."},{"id":"G02:7","text":"그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.","paragraph":0,"memberIds":["G02:7"],"topic":"그렇게 만든 공간에는 돌봄과 가꿈이 주는 안전함과 편안함이 없다."}]}]},"examplePractice":true,"id":"U62-E01-B1","type":"ox","answer":"O","changed":"점검표에 ✓만 적은 화분은 겉모습만 꾸민 관리에 해당한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"2d4c6231f72af62dd987113a535dd560e759f5a08c10917af386db501cf1d80e"}]},{"name":"U62-E01-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"2문단 · 새 예시 적용","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 2문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 2문단]\n‘가꿈’은 식물이나 그것을 기르는 장소 등을 손질하고 보살핀다는 의미이다. 좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다. ‘돌봄’은 관심 있게 보살피는 것을 의미한다. 두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다. 단순히 도시와 건축을 관리하는 것은 보살핌이 아니다. 어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다. 그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n서윤이네 반 창가에는 화분이 두 개 있다. 서윤이는 날마다 흙이 말랐는지 살피고 물을 주며 한 화분을 돌본다. 다른 화분은 겉에 예쁜 그림만 그려 놓고, 점검표에 ‘물 주기 ✓’만 적어 두었다. 흙이 바싹 말라도 아무도 들여다보지 않았다. 한 달 뒤, 서윤이가 돌본 화분은 꽃을 피웠고, 겉만 꾸민 화분은 시들어 버렸다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"날마다 살피고 물을 주는 서윤이는 관심을 두고 지속해서 보살피는 가꿈·돌봄에, 겉에 그림만 그리고 점검표에 ✓만 적은 화분은 배려·공감 없이 법적 요건만 갖춘 관리(겉모습만 꾸미기)에 대응한다. 시든 화분은 안전함과 편안함이 없는 공간과 같다.\n근거: “두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다.” “어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.” “그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.”\n2문단에서 확인할 수 있어요.","evidence":{"title":"교실 창가의 화분 두 개","statement":"점검표에 ✓만 적은 화분은 겉모습만 꾸민 관리에 해당한다.","explanation":"날마다 살피고 물을 주는 서윤이는 관심을 두고 지속해서 보살피는 가꿈·돌봄에, 겉에 그림만 그리고 점검표에 ✓만 적은 화분은 배려·공감 없이 법적 요건만 갖춘 관리(겉모습만 꾸미기)에 대응한다. 시든 화분은 안전함과 편안함이 없는 공간과 같다.\n근거: “두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다.” “어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.” “그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.”\n2문단에서 확인할 수 있어요.","valid":["G02:4","G02:6","G02:7"],"sources":[{"id":"G02","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"2문단","sentences":[{"id":"G02:1","text":"‘가꿈’은 식물이나 그것을 기르는 장소 등을 손질하고 보살핀다는 의미이다.","paragraph":0,"memberIds":["G02:1"],"topic":"'가꿈'은 식물이나 식물을 기르는 곳을 손질하고 보살핀다는 뜻이다."},{"id":"G02:2","text":"좋은 상태로 만들려고 보살피고 꾸려 가는 행위인 것이다.","paragraph":0,"memberIds":["G02:2"],"topic":"다시 말해 좋은 상태로 만들려고 보살피고 잘 이끌어 가는(꾸려 가는) 일이다."},{"id":"G02:3","text":"‘돌봄’은 관심 있게 보살피는 것을 의미한다.","paragraph":0,"memberIds":["G02:3"],"topic":"'돌봄'은 관심을 가지고 보살피는 것을 뜻한다."},{"id":"G02:4","text":"두 단어 모두 정성을 기울여 대상이나 공간을 보호하며 관심을 두고 지속해서 보살피는 일을 의미한다.","paragraph":0,"memberIds":["G02:4"],"topic":"두 낱말 모두 정성을 다해 대상이나 공간을 지키면서, 관심을 두고 꾸준히(지속해서) 보살피는 일을 뜻한다."},{"id":"G02:5","text":"단순히 도시와 건축을 관리하는 것은 보살핌이 아니다.","paragraph":0,"memberIds":["G02:5"],"topic":"도시와 건물을 그저 관리하기만 하는 것은 보살핌이 아니다."},{"id":"G02:6","text":"어떠한 배려나 공감 없이 최소한의 법적 요건만 갖추어 계획하는 행위는 겉모습을 꾸미기만 하는 관리의 모습이다.","paragraph":0,"memberIds":["G02:6"],"topic":"배려나 공감 없이 법에서 정한 가장 낮은 기준(최소한의 법적 요건)만 맞추어 계획하는 것은 겉모습만 꾸미는 '관리'일 뿐이다."},{"id":"G02:7","text":"그 안에 돌봄과 가꿈이 줄 수 있는 안전함과 편안함은 없다.","paragraph":0,"memberIds":["G02:7"],"topic":"그렇게 만든 공간에는 돌봄과 가꿈이 주는 안전함과 편안함이 없다."}]}]},"examplePractice":true,"id":"U62-E01-B2","type":"ox","answer":"X","changed":"점검표에 ✓만 적은 화분은 지속해서 보살피는 돌봄에 해당한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":15,"end":29,"before":"지속해서 보살피는 돌봄에 ","after":"겉모습만 꾸민 관리에 "}],"editorSourceVersion":"04571c92f984a55d4fc9bf841d30a10939f587cba85959eea7f71cea32591fa8"}]},{"name":"U62-H03-02-B1 · 뒷전의 뜻","items":[{"paragraphCount":1,"readingLabel":"3문단 · 핵심 읽기 2/5단계","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 3문단","passage":"[핵심 문장 · 3문단]\n단지 꾸미기에 열중한 나머지 정작 제일 중요한 사람에 대한 배려는 뒷전이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"‘뒷전’은 뒤로 미뤄 둔 차례를 말한다.\n근거: “단지 꾸미기에 열중한 나머지 정작 제일 중요한 사람에 대한 배려는 뒷전이다.”","evidence":{"title":"뒷전의 뜻","statement":"‘뒷전이다’는 사람에 대한 배려가 뒤로 밀려나 있다는 뜻이다.","explanation":"‘뒷전’은 뒤로 미뤄 둔 차례를 말한다.\n근거: “단지 꾸미기에 열중한 나머지 정작 제일 중요한 사람에 대한 배려는 뒷전이다.”","valid":["G03:2"],"sources":[{"id":"G03","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"3문단","sentences":[{"id":"G03:2","text":"단지 꾸미기에 열중한 나머지 정작 제일 중요한 사람에 대한 배려는 뒷전이다.","paragraph":0,"memberIds":["G03:2"],"topic":"꾸미는 데에만 정신을 쏟다(열중하다) 보니, 정작 가장 중요한 사람에 대한 배려는 뒤로 밀려나 있다(뒷전이다)."}]}]},"shortComparison":true,"focusQuotes":[{"id":"G03:2","text":"단지 꾸미기에 열중한 나머지 정작 제일 중요한 사람에 대한 배려는 뒷전이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U62-H03-02-B1","type":"ox","answer":"O","changed":"‘뒷전이다’는 사람에 대한 배려가 뒤로 밀려나 있다는 뜻이다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":2,"progressiveTotal":5,"progressiveLabel":"표현 바꿔 읽기","learningFocus":"뒷전의 뜻","hintGuide":"‘뒷전’을 쉬운 말로 바꾸어 보세요.","synthesis":false,"editorSourceVersion":"bc43bf66c395a153370d21398364d03f2dd11eb473cd73ead80fea81826408ba"}]},{"name":"U62-P04-01-B1 · 비교","items":[{"paragraphCount":1,"readingLabel":"4문단","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 4문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 4문단]\n법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다. 경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다. 기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다. 이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다. 자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보하고 더 많은 사람이 정류장에서 대기할 수 있게 도와준다. 좁은 인도에 사용하지 않는 의자들이 시민의 통행을 가로막는 경우도 많은데 접이식 의자를 설치하면 이러한 부분도 해결할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.\n근거: “법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.”\n4문단에서 확인할 수 있어요.","evidence":{"title":"사용자를 배려한 계획이 가꿈의 시작이다.","statement":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.","explanation":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.\n근거: “법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.”\n4문단에서 확인할 수 있어요.","valid":["G04:1"],"sources":[{"id":"G04","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"4문단","sentences":[{"id":"G04:1","text":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.","paragraph":0,"memberIds":["G04:1"],"topic":"법과 규칙(법규)에만 맞춰 계획하는 것이 아니라, 쓰는 사람(사용자)을 배려해서 계획하는 것이 가꿈의 시작이다."},{"id":"G04:2","text":"경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다.","paragraph":0,"memberIds":["G04:2"],"topic":"경기도 수원시의 수원 시청 앞 버스 정류장(승강장)은 작은 가꿈을 실제로 하고(실천하고) 있다."},{"id":"G04:3","text":"기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다.","paragraph":0,"memberIds":["G04:3"],"topic":"원래 정류장의 의자들은 한자리에 붙어 있어서(고정되어 있어서) 자리를 많이 차지했다. 그래서 사람이 많아지면 휠체어를 타는 장애인은 몹시 불편하고, 눈과 비를 피할 수도 없었다."},{"id":"G04:4","text":"이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다.","paragraph":0,"memberIds":["G04:4"],"topic":"이런 불편을 없애고 모두를 배려하려고 정류장에 저절로 접히는 의자(자동 접이식 의자)를 놓았다."},{"id":"G04:5","text":"자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보하고 더 많은 사람이 정류장에서 대기할 수 있게 도와준다.","paragraph":0,"memberIds":["G04:5"],"topic":"자동 접이식 의자는 아무도 앉지 않을 때 저절로 접혀서 정류장 공간을 넓혀 주고, 더 많은 사람이 정류장에서 기다릴 수 있게 해 준다."},{"id":"G04:6","text":"좁은 인도에 사용하지 않는 의자들이 시민의 통행을 가로막는 경우도 많은데 접이식 의자를 설치하면 이러한 부분도 해결할 수 있다.","paragraph":0,"memberIds":["G04:6"],"topic":"좁은 인도에서는 아무도 안 쓰는 의자가 사람들이 지나가는 길을 막는 일도 많은데, 접이식 의자를 놓으면 이 문제도 풀 수 있다."}]}]},"id":"U62-P04-01-B1","type":"ox","answer":"O","changed":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"editorSourceVersion":"a62d4f6ab70f572ef71f31477679b68fc79c18c398856821fabd51ad884dd753"}]},{"name":"U62-P04-01-B2 · 비교","items":[{"paragraphCount":1,"readingLabel":"4문단","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 4문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 4문단]\n법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다. 경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다. 기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다. 이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다. 자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보하고 더 많은 사람이 정류장에서 대기할 수 있게 도와준다. 좁은 인도에 사용하지 않는 의자들이 시민의 통행을 가로막는 경우도 많은데 접이식 의자를 설치하면 이러한 부분도 해결할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.\n근거: “법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.”\n4문단에서 확인할 수 있어요.","evidence":{"title":"사용자를 배려한 계획이 가꿈의 시작이다.","statement":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.","explanation":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.\n근거: “법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.”\n4문단에서 확인할 수 있어요.","valid":["G04:1"],"sources":[{"id":"G04","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"4문단","sentences":[{"id":"G04:1","text":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.","paragraph":0,"memberIds":["G04:1"],"topic":"법과 규칙(법규)에만 맞춰 계획하는 것이 아니라, 쓰는 사람(사용자)을 배려해서 계획하는 것이 가꿈의 시작이다."},{"id":"G04:2","text":"경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다.","paragraph":0,"memberIds":["G04:2"],"topic":"경기도 수원시의 수원 시청 앞 버스 정류장(승강장)은 작은 가꿈을 실제로 하고(실천하고) 있다."},{"id":"G04:3","text":"기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다.","paragraph":0,"memberIds":["G04:3"],"topic":"원래 정류장의 의자들은 한자리에 붙어 있어서(고정되어 있어서) 자리를 많이 차지했다. 그래서 사람이 많아지면 휠체어를 타는 장애인은 몹시 불편하고, 눈과 비를 피할 수도 없었다."},{"id":"G04:4","text":"이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다.","paragraph":0,"memberIds":["G04:4"],"topic":"이런 불편을 없애고 모두를 배려하려고 정류장에 저절로 접히는 의자(자동 접이식 의자)를 놓았다."},{"id":"G04:5","text":"자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보하고 더 많은 사람이 정류장에서 대기할 수 있게 도와준다.","paragraph":0,"memberIds":["G04:5"],"topic":"자동 접이식 의자는 아무도 앉지 않을 때 저절로 접혀서 정류장 공간을 넓혀 주고, 더 많은 사람이 정류장에서 기다릴 수 있게 해 준다."},{"id":"G04:6","text":"좁은 인도에 사용하지 않는 의자들이 시민의 통행을 가로막는 경우도 많은데 접이식 의자를 설치하면 이러한 부분도 해결할 수 있다.","paragraph":0,"memberIds":["G04:6"],"topic":"좁은 인도에서는 아무도 안 쓰는 의자가 사람들이 지나가는 길을 막는 일도 많은데, 접이식 의자를 놓으면 이 문제도 풀 수 있다."}]}]},"id":"U62-P04-01-B2","type":"ox","answer":"X","changed":"사용자를 배려하여 계획하는 것이 아닌, 법규에만 맞춰 계획하는 것이 가꿈의 시작이다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"claimEdits":[{"start":0,"end":5,"before":"사용자를 ","after":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 "},{"start":18,"end":38,"before":"아닌, 법규에만 맞춰 계획하는 것이 ","after":""}],"editorSourceVersion":"a5be9f38954d67ffbec6016d586d13fa06e004449b4c48d87e2eb0dc93e6c359"}]},{"name":"U62-H04-05-B1 · 4문단의 핵심","items":[{"paragraphCount":1,"readingLabel":"4문단 · 핵심 읽기 5/5단계","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 4문단","passage":"[문단 전체 · 4문단]\n법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다. 경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다. 기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다. 이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다. 자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보하고 더 많은 사람이 정류장에서 대기할 수 있게 도와준다. 좁은 인도에 사용하지 않는 의자들이 시민의 통행을 가로막는 경우도 많은데 접이식 의자를 설치하면 이러한 부분도 해결할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"4문단은 가꿈의 시작을 사용자를 배려한 계획으로 정리하고, 수원 시청 앞 버스 승강장 사례를 든다.\n근거: “법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.” “경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다.”","evidence":{"title":"4문단의 핵심","statement":"4문단은 사용자를 배려한 계획이 가꿈의 시작임을 수원 시청 앞 버스 승강장의 사례로 보여 준다.","explanation":"4문단은 가꿈의 시작을 사용자를 배려한 계획으로 정리하고, 수원 시청 앞 버스 승강장 사례를 든다.\n근거: “법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.” “경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다.”","valid":["G04:1","G04:2"],"sources":[{"id":"G04","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"4문단","sentences":[{"id":"G04:1","text":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다.","paragraph":0,"memberIds":["G04:1"],"topic":"법과 규칙(법규)에만 맞춰 계획하는 것이 아니라, 쓰는 사람(사용자)을 배려해서 계획하는 것이 가꿈의 시작이다."},{"id":"G04:2","text":"경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다.","paragraph":0,"memberIds":["G04:2"],"topic":"경기도 수원시의 수원 시청 앞 버스 정류장(승강장)은 작은 가꿈을 실제로 하고(실천하고) 있다."},{"id":"G04:3","text":"기존 버스 승강장에 설치된 의자들은 고정되어 있어 많은 공간을 차지하고, 사람들이 많아지거나 하면 휠체어를 사용하는 장애인은 큰 불편을 겪을 뿐 아니라 눈과 비를 피할 수도 없다.","paragraph":0,"memberIds":["G04:3"],"topic":"원래 정류장의 의자들은 한자리에 붙어 있어서(고정되어 있어서) 자리를 많이 차지했다. 그래서 사람이 많아지면 휠체어를 타는 장애인은 몹시 불편하고, 눈과 비를 피할 수도 없었다."},{"id":"G04:4","text":"이런 불편을 해결하고 모두를 배려하기 위해 버스 승강장에 자동 접이식 의자를 설치하였다.","paragraph":0,"memberIds":["G04:4"],"topic":"이런 불편을 없애고 모두를 배려하려고 정류장에 저절로 접히는 의자(자동 접이식 의자)를 놓았다."},{"id":"G04:5","text":"자동 접이식 의자는 사람이 이용하지 않을 때는 자동으로 접혀서 정류장 공간을 확보하고 더 많은 사람이 정류장에서 대기할 수 있게 도와준다.","paragraph":0,"memberIds":["G04:5"],"topic":"자동 접이식 의자는 아무도 앉지 않을 때 저절로 접혀서 정류장 공간을 넓혀 주고, 더 많은 사람이 정류장에서 기다릴 수 있게 해 준다."},{"id":"G04:6","text":"좁은 인도에 사용하지 않는 의자들이 시민의 통행을 가로막는 경우도 많은데 접이식 의자를 설치하면 이러한 부분도 해결할 수 있다.","paragraph":0,"memberIds":["G04:6"],"topic":"좁은 인도에서는 아무도 안 쓰는 의자가 사람들이 지나가는 길을 막는 일도 많은데, 접이식 의자를 놓으면 이 문제도 풀 수 있다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"G04:1","text":"법규에만 맞춰 계획하는 것이 아닌, 사용자를 배려하여 계획하는 것이 가꿈의 시작이다."},{"id":"G04:2","text":"경기도 수원시의 수원 시청 앞 버스 승강장은 조그마한 가꿈을 실천하고 있다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U62-H04-05-B1","type":"ox","answer":"O","changed":"4문단은 사용자를 배려한 계획이 가꿈의 시작임을 수원 시청 앞 버스 승강장의 사례로 보여 준다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"4문단의 핵심","hintGuide":"4문단 첫 문장과 사례가 어떻게 이어지는지 보세요.","synthesis":true,"editorSourceVersion":"9765232df67c1bd636dea4ef507aab36a70026a00fd940c344c24470fa4af44d"}]},{"name":"U62-E02-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"3문단 · 새 예시 적용","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 3문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 3문단]\n매일 걷는 길과 도로, 종종 사용하는 공중화장실, 편리하게 이용하는 대중교통, 공원의 편의 시설 등 우리가 모두 함께 사용하는 공간 속에서 조금씩 보살핌의 의미가 퇴색되어 가는 듯하다. 단지 꾸미기에 열중한 나머지 정작 제일 중요한 사람에 대한 배려는 뒷전이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n학교 축제 날, 학생회는 복도를 풍선과 깃발로 화려하게 꾸미는 데 온 힘을 쏟았다. 그런데 장식 상자와 큰 안내판이 복도 한가운데를 막아서, 다리를 다쳐 목발을 짚은 도윤이는 지나가기가 어려웠다. 복도는 사람이 다니는 곳이다. 아무리 예쁘게 꾸며도 그 길을 쓰는 사람을 먼저 생각하지 않으면 소용이 없다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"복도를 꾸미는 데 온 힘을 쏟은 학생회는 꾸미기에 열중하는 모습에, 목발을 짚은 도윤이가 지나가기 어려운 것은 정작 제일 중요한 사람에 대한 배려가 뒷전인 것에 대응한다. 모두 함께 쓰는 복도는 길과 도로, 공중화장실처럼 함께 쓰는 공간과 같다.\n근거: “매일 걷는 길과 도로, 종종 사용하는 공중화장실, 편리하게 이용하는 대중교통, 공원의 편의 시설 등 우리가 모두 함께 사용하는 공간 속에서 조금씩 보살핌의 의미가 퇴색되어 가는 듯하다.” “단지 꾸미기에 열중한 나머지 정작 제일 중요한 사람에 대한 배려는 뒷전이다.”\n3문단에서 확인할 수 있어요.","evidence":{"title":"축제 날 복도","statement":"복도를 막은 장식 상자는 사람에 대한 배려가 뒷전이 된 모습이다.","explanation":"복도를 꾸미는 데 온 힘을 쏟은 학생회는 꾸미기에 열중하는 모습에, 목발을 짚은 도윤이가 지나가기 어려운 것은 정작 제일 중요한 사람에 대한 배려가 뒷전인 것에 대응한다. 모두 함께 쓰는 복도는 길과 도로, 공중화장실처럼 함께 쓰는 공간과 같다.\n근거: “매일 걷는 길과 도로, 종종 사용하는 공중화장실, 편리하게 이용하는 대중교통, 공원의 편의 시설 등 우리가 모두 함께 사용하는 공간 속에서 조금씩 보살핌의 의미가 퇴색되어 가는 듯하다.” “단지 꾸미기에 열중한 나머지 정작 제일 중요한 사람에 대한 배려는 뒷전이다.”\n3문단에서 확인할 수 있어요.","valid":["G03:1","G03:2"],"sources":[{"id":"G03","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"3문단","sentences":[{"id":"G03:1","text":"매일 걷는 길과 도로, 종종 사용하는 공중화장실, 편리하게 이용하는 대중교통, 공원의 편의 시설 등 우리가 모두 함께 사용하는 공간 속에서 조금씩 보살핌의 의미가 퇴색되어 가는 듯하다.","paragraph":0,"memberIds":["G03:1"],"topic":"매일 걷는 길과 도로, 가끔 쓰는 공중화장실, 편하게 타는 대중교통, 공원의 편의 시설처럼 우리 모두가 함께 쓰는 공간에서 보살핌의 뜻이 조금씩 희미해지는(퇴색되는) 것 같다."},{"id":"G03:2","text":"단지 꾸미기에 열중한 나머지 정작 제일 중요한 사람에 대한 배려는 뒷전이다.","paragraph":0,"memberIds":["G03:2"],"topic":"꾸미는 데에만 정신을 쏟다(열중하다) 보니, 정작 가장 중요한 사람에 대한 배려는 뒤로 밀려나 있다(뒷전이다)."}]}]},"examplePractice":true,"id":"U62-E02-B1","type":"ox","answer":"O","changed":"복도를 막은 장식 상자는 사람에 대한 배려가 뒷전이 된 모습이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"9c2e7b480dda158342af4141f19c75f855aa8c56e8aee095bd3821d266bfce16"}]}]};})(window);
